import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { OverlayProvider } from "@/registry/erbium/ui/overlay-provider";
import { SkeletonProvider } from "@/registry/erbium/ui/skeleton";
import { Toaster } from "@/registry/erbium/ui/toast";
import type { ReactNode } from "react";

export const ShowcaseProviders = ({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) => (
  <CSPProvider disableStyleElements>
    <SkeletonProvider>
      <OverlayProvider>
        {children}
        {toast && <Toaster />}
      </OverlayProvider>
    </SkeletonProvider>
  </CSPProvider>
);

export const ShowcaseSurface = ({ children }: { children?: ReactNode }) => (
  <div
    data-slot="component-preview"
    className="relative isolate mx-auto flex min-h-64 w-full min-w-0 max-w-3xl items-center justify-center gap-section p-5 font-sans text-foreground contain-layout sm:p-8 [&>.min-w-72.max-w-2xl]:flex [&>.min-w-72.max-w-2xl]:flex-col [&>.min-w-72.max-w-2xl]:items-center [&>.min-w-72.max-w-2xl]:justify-center"
  >
    {children}
  </div>
);

export const skills = [
  { ana: 86, ben: 64, skill: "Speed" },
  { ana: 58, ben: 88, skill: "Strength" },
  { ana: 74, ben: 70, skill: "Stamina" },
  { ana: 92, ben: 55, skill: "Agility" },
  { ana: 66, ben: 80, skill: "Defense" },
  { ana: 80, ben: 72, skill: "Vision" },
];

export const players = [
  { key: "ana", label: "Ana" },
  { key: "ben", label: "Ben" },
] as const;

// Generated from the Erbium showcase catalog and shared Markdown.
import { ShowcaseProviders, ShowcaseSurface } from "../preview";
import type { Meta, StoryObj } from "@storybook/react";

import { RadarChart } from "@/registry/erbium/charts/radar-chart";

import PlaygroundExample from "./variants/playground";

const PlaygroundSource = "import { RadarChart } from \"@/registry/erbium/charts/radar-chart\";\nimport { players, skills } from \"../examples/data\";\n\nconst Example = (args: { legend: boolean; points: boolean; rings: number; tooltip: boolean }) => (\n  <div className=\"w-md max-w-full p-4\">\n    <RadarChart\n      ariaLabel=\"Skill ratings for two players\"\n      data={skills}\n      index=\"skill\"\n      series={players}\n      max={100}\n      initialWidth={400}\n      {...args}\n    />\n  </div>\n);\n\nexport default Example;\n";

const meta = {
  component: RadarChart,
  parameters: {
    docs: {
      description: {
        component: "## Usage\n\nPass one row per axis, with one numeric field per series. Set `max` when several radar charts should be compared, so their outer rings mean the same value.\n\n```tsx\nimport { RadarChart } from \"@/registry/erbium/charts/radar-chart\";\n\n<RadarChart ariaLabel=\"Skills by player\" data={skills} index=\"skill\" series={players} max={100} />;\n```\n\nRadar charts need axes on the same scale. With fewer than five axes, or axes in different units, use a [Bar Chart](/docs/charts/bar-chart).",
      },
    },
    layout: "centered",
  },
  tags: ["autodocs"],
} satisfies Meta<typeof RadarChart>;

export default { ...meta, title: "Charts/Radar Chart",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

export const Playground: StoryObj<{
  legend: boolean;
  points: boolean;
  rings: number;
  tooltip: boolean;
}> = {
  argTypes: {
    legend: { control: "boolean" },
    points: { control: "boolean" },
    rings: { control: { max: 8, min: 2, type: "number" } },
    tooltip: { control: "boolean" },
  },
  args: { legend: true, points: false, rings: 4, tooltip: true },
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: PlaygroundSource },
    },
  },
  render: PlaygroundExample,
};

import { RadarChart } from "@/registry/erbium/charts/radar-chart";
import { players, skills } from "../examples/data";

const Example = (args: { legend: boolean; points: boolean; rings: number; tooltip: boolean }) => (
  <div className="w-md max-w-full p-4">
    <RadarChart
      ariaLabel="Skill ratings for two players"
      data={skills}
      index="skill"
      series={players}
      max={100}
      initialWidth={400}
      {...args}
    />
  </div>
);

export default Example;
